AppError:
export type AppError = {
	code: string,
	message: string,
	remedy: string | null,
	staleTranscript?: StaleTranscriptDto | null,
};

Question:
export type Question = {
	question: string,
	header: string,
	multiSelect: boolean,
	options: QuestionOption[],
};

QuestionOption:
export type QuestionOption = {
	label: string,
	description: string,
};

Session:
export type Session = {
	id: string,
	workstreamId: string,
	stage: Stage,
	harness: Harness,
	claudeSessionId: string | null,
	cwd: string,
	state: SessionState,
	model: string | null,
	costUsd: number | null,
	startedAt: number | null,
	endedAt: number | null,
	exitSummary: string | null,
	title?: string | null,
	preview?: string | null,
	archivedAt?: number | null,
	/**  Mid-turn or starting; `state` alone reads `running` for an idle live harness. */
	working?: boolean,
	/**  When the session's newest log event landed; `None` before its first. */
	lastActiveAt?: number | null,
	/**  Only a running or paused goal; an ended one is read through `get_goal`. */
	goal?: GoalBrief | null,
	origin?: SessionOrigin,
	/**  The session this one came from: its spawning agent, or the implement session a validation checks. */
	parentSessionId?: string | null,
	/**  What it launched with, or was asked to start on; a retry of a failed start shows it. */
	effort?: string | null,
	/**  The mode its start, last launch or last mode change asked for; `None` is Auto, the stage's own. */
	requestedPermissionMode?: PermissionMode | null,
};

SessionLogEntryDto:
export type SessionLogEntryDto = {
	seq: number | null,
	kind: string,
	event: SessionEvent,
	createdAt: number | null,
};
